@RestController
public class ResourceController {
    // Idempotent: Multiple calls result in the same state
    @PutMapping("/items/{id}")
    public ResponseEntity<Item> updateItem(@PathVariable String id, @RequestBody Item item) {
        return ResponseEntity.ok(repository.save(item));
    }

    // Non-Idempotent: Multiple calls create multiple resources
    @PostMapping("/items")
    public ResponseEntity<Item> createItem(@RequestBody Item item) {
        return ResponseEntity.status(HttpStatus.CREATED).body(repository.save(item));
    }
}
